commands.windows:
# Standalone example: Reports Windows hotpatch readiness as one line: edition, build, VBS state and whether the hotpatch policy is set. It does not evaluate eligibility or Arm64 CHPE, and reports not applicable on Linux and macOS.
$cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
$vbs = 'unknown'
try {
  $dg = Get-CimInstance -ClassName Win32_DeviceGuard -Namespace root\Microsoft\Windows\DeviceGuard -ErrorAction Stop
  $vbs = @('off', 'enabled', 'running')[[int]$dg.VirtualizationBasedSecurityStatus]
} catch {}
$pm = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device\Update' -ErrorAction SilentlyContinue
$enrolled = [bool]($pm -and $pm.AllowRebootlessUpdates -eq 1)
"$($cv.EditionID) build $($cv.CurrentBuildNumber).$($cv.UBR) vbs=$vbs enrolled=$enrolled"
